<?php
use Typecho\Common;
use Typecho\Cookie;
use Typecho\Db;
use Typecho\Plugin;
use Typecho\Request;
use Typecho\Response;
use Typecho\Widget;
use Widget\Options;
use Widget\User;

/**
 * Widget\User::login() against a real SQLite users table: legacy hashes are upgraded on login,
 * modern hashes are left alone.
 */
final class LoginRehashTest extends SqliteTestCase
{
    /** phpass portable hash of 's3cret-密码', generated by the original phpass 0.2 PasswordHash(8, true) */
    private const PHPASS_HASH = '$P$B2EpzX6laLl8psZuLXUfD3uk6XUwro/';

    private const PASSWORD = 's3cret-密码';

    protected function setUp(): void
    {
        parent::setUp();
        Widget::destroy();
        Plugin::init([]);

        // a parameterised Options widget skips the database, User only needs it to exist
        Options::alloc(['plugins' => []]);
    }

    protected function tearDown(): void
    {
        unset($_COOKIE[Cookie::getPrefix() . '__typecho_uid'], $_COOKIE[Cookie::getPrefix() . '__typecho_authCode']);
        Widget::destroy();
        Plugin::init([]);
        parent::tearDown();
    }

    private function createUser(string $hash): int
    {
        return (int) $this->db->query($this->db->insert('table.users')->rows([
            'name' => 'admin', 'password' => $hash, 'mail' => 'admin@example.com',
            'screenName' => 'admin', 'group' => 'administrator', 'created' => 1700000000,
        ]), Db::WRITE, Db::INSERT);
    }

    private function storedHash(int $uid): string
    {
        return $this->db->fetchObject($this->db->select('password')
            ->from('table.users')->where('uid = ?', $uid))->password;
    }

    private function login(string $name, string $password, ?User &$widget = null): bool
    {
        $widget = User::allocWithAlias(uniqid('login'));

        // temporarily: skip commitLogin(), which would send cookies
        return $widget->login($name, $password, true);
    }

    public function testPhpassHashIsUpgradedOnLogin(): void
    {
        $uid = $this->createUser(self::PHPASS_HASH);

        $this->assertFalse($this->login('admin', 'wrong'));
        $this->assertSame(self::PHPASS_HASH, $this->storedHash($uid), 'failed login must not rehash');

        $this->assertTrue($this->login('admin', self::PASSWORD, $widget));

        $upgraded = $this->storedHash($uid);
        $this->assertNotSame(self::PHPASS_HASH, $upgraded);
        $this->assertMatchesRegularExpression('/^\$(2y|argon2i|argon2id)\$/', $upgraded);
        $this->assertFalse(password_needs_rehash($upgraded, PASSWORD_DEFAULT));
        $this->assertTrue(password_verify(self::PASSWORD, $upgraded));

        // the in-memory row is updated as well
        $this->assertSame($upgraded, $widget->password);

        $this->assertTrue($this->login('admin', self::PASSWORD));
        $this->assertSame($upgraded, $this->storedHash($uid));
    }

    public function testLegacyMd5HashIsUpgradedOnLoginByMail(): void
    {
        $uid = $this->createUser(md5('admin'));

        $this->assertTrue($this->login('admin@example.com', 'admin'));
        $this->assertTrue(password_verify('admin', $this->storedHash($uid)));
    }

    public function testModernHashIsNotRewritten(): void
    {
        $hash = password_hash(self::PASSWORD, PASSWORD_DEFAULT);
        $uid = $this->createUser($hash);

        $this->assertTrue($this->login('admin', self::PASSWORD));
        $this->assertSame($hash, $this->storedHash($uid));
    }

    public function testHashValidatePluginTakesPrecedenceAndIsNotRehashed(): void
    {
        $uid = $this->createUser(self::PHPASS_HASH);
        Plugin::factory(User::class)->hashValidate = function (string $password, string $hash): bool {
            return 'plugin-pass' === $password;
        };

        $this->assertFalse($this->login('admin', self::PASSWORD));
        $this->assertTrue($this->login('admin', 'plugin-pass'));
        $this->assertSame(self::PHPASS_HASH, $this->storedHash($uid));
    }

    /**
     * hasLogin() feeds the client-controlled authCode cookie into hashValidate(), which now also
     * runs password_verify() / phpass: a forged high-cost hash must be refused before hashing.
     */
    public function testAuthCodeCookieOnlyAcceptsTypechoHash(): void
    {
        $uid = $this->createUser(self::PHPASS_HASH);
        $authCode = bin2hex(random_bytes(16));
        $this->db->query($this->db->update('table.users')->rows(['authCode' => $authCode])
            ->where('uid = ?', $uid));

        $hasLogin = function (string $cookie) use ($uid): bool {
            // keyed like Cookie::get() looks them up, whatever prefix another test left behind
            $_COOKIE[Cookie::getPrefix() . '__typecho_uid'] = (string) $uid;
            $_COOKIE[Cookie::getPrefix() . '__typecho_authCode'] = $cookie;

            // constructed directly: alloc() would run execute() and cache hasLogin() before the cookie is set
            $request = Request::getInstance();
            $user = new User(new Widget\Request($request), new Widget\Response($request, Response::getInstance()));
            return $user->hasLogin();
        };

        $this->assertTrue($hasLogin(Common::hash($authCode)));
        $this->assertFalse($hasLogin(Common::hash('other')));
        $this->assertFalse($hasLogin(password_hash($authCode, PASSWORD_BCRYPT, ['cost' => 4])));
        $this->assertFalse($hasLogin('$P$B2EpzX6laLl8psZuLXUfD3uk6XUwro/'));
        $this->assertFalse($hasLogin(md5($authCode)));
    }
}
